import java.util.*;
import java.util.stream.*;
public class CoffeeOrder {
  public static void main(String[] args) {
    List<String> coffees = List.of("Cappuccino", "Americano", "Espresso",
        "Cortado", "Mocha", "Cappuccino", "Flat White", "Latte");
    List<String> coffeesEndingInO = coffees.stream()
        .filter(s -> s.endsWith("o"))
        .sorted()
        .distinct()
        .collect(Collectors.toList());
    System.out.println(coffeesEndingInO);   // [Americano, Cappuccino, Cortado, Espresso]
  }
}

public class StreamPuzzle {
  public static void main(String[] args) {
    SongSearch songSearch = new SongSearch();
    songSearch.printTopFiveSongs();
    songSearch.search("The Beatles");
    songSearch.search("The Beach Boys");
  }
}
class SongSearch {
  private final List<Song> songs = new JukeboxData.Songs().getSongs();
  void printTopFiveSongs() {
    List<String> topFive = songs.stream()
        .sorted(Comparator.comparingInt(Song::getTimesPlayed))
        .map(song -> song.getTitle()).limit(5).collect(Collectors.toList());
    System.out.println(topFive);
  }
  void search(String artist) {
    Optional<Song> result = songs.stream()
        .filter(song -> song.getArtist().equals(artist)).findFirst();
    if (result.isPresent()) System.out.println(result.get().getTitle());
    else System.out.println("No songs found by: " + artist);
  }
}
